126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
130	        rejectBlankOwnerFields(ownerFieldsDto);
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        if (!sharesHousehold) {
133	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
134	        }
135	        rejectCityAtCapacity(ownerFieldsDto.getCity());
136	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
137	        rejectDailyRegistrationLimit(registrationDate);
138	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
139	        rejectDuplicateTelephone(normalizedTelephone);
140	        ownerFieldsDto.setTelephone(normalizedTelephone);
141	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
142	        HttpHeaders headers = new HttpHeaders();
143	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
144	        owner.setRegistrationDate(registrationDate);
145	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
146	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
147	        if (sharesHousehold) {
148	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
149	        }
150	        this.clinicService.saveOwner(owner);
151	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
152	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
155	        ownerDto.setMembershipTier(applyHouseholdTier(owner, ownerDto.getMembershipTier()));
156	        headers.setLocation(UriComponentsBuilder.newInstance()
157	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
158	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
159	    }
