255	    /**
256	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
257	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
258	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
259	     * blank (e.g. {@code "   "}). The offending field names are reported through an
260	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
261	     * as a 400 response carrying an {@code errors} array of field names.
262	     *
263	     * @param ownerFieldsDto the submitted owner fields
264	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
265	     */
266	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
267	        List<String> blankFields = new ArrayList<>();
268	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
269	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
270	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
271	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
272	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
273	        if (!blankFields.isEmpty()) {
274	            throw new InvalidOwnerFieldsException(blankFields);
275	        }
276	    }
277	
278	    private void addIfBlank(List<String> blankFields, String field, String value) {
279	        if (value != null && value.isBlank()) {
280	            blankFields.add(field);
281	        }
282	    }
283	
284	    /**
285	     * Normalizes an owner's optional email address. When present it is stored and returned
286	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
287	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
288	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
289	     * method runs.
290	     *
291	     * @param email the raw email value from the request, or {@code null} when omitted
292	     * @return the lower-cased email, or {@code null} when none was supplied
293	     */
294	    private String normalizeEmail(String email) {
295	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
296	    }
297	
298	    /**
299	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
300	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
301	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
302	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
303	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
304	     *
305	     * @param city the city of the owner being created
306	     * @param lastName the last name of the owner being created
307	     * @return the formatted customer code
308	     */
309	    private String nextCustomerCode(String city, String lastName) {
310	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
311	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
312	        long sequence = this.clinicService.findAllOwners().stream()
313	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
314	            .count() + 1L;
315	        return String.format("%s-%s-%04d", city3, last3, sequence);
316	    }
317	
318	    /**
319	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
320	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
321	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
322	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
323	     * new owner and surfaced as the read-only {@code namesakeCount} field.
324	     *
325	     * @param firstName the first name of the owner being created
326	     * @param lastName the last name of the owner being created
327	     * @return the number of existing owners with the same first and last name (case-insensitive)
328	     */
329	    private int namesakeCount(String firstName, String lastName) {
330	        return (int) this.clinicService.findAllOwners().stream()
331	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
332	                && equalsIgnoreCase(owner.getLastName(), lastName))
333	            .count();
334	    }
